using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Workshop;
using HarborValeGreybox.Driving;
namespace HarborValeGreybox.Racing {
public sealed class NpcAudioPlayerProbe:MonoBehaviour {
 static string folder;readonly List<string> checks=new List<string>();bool failed;FinchVehicle car;AudioListener listener;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"--npc-audio-check-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<a.Length?Path.GetFullPath(a[i+1]):null;if(folder!=null)Directory.CreateDirectory(folder);}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder!=null){var go=new GameObject("Actual listener NPC distance verification");DontDestroyOnLoad(go);go.AddComponent<NpcAudioPlayerProbe>();}}
 void Check(bool ok,string text){checks.Add((ok?"PASS ":"FAIL ")+text);File.WriteAllLines(folder+"/results.txt",checks);if(!ok){failed=true;Application.Quit(1);throw new Exception(text);}}
 void OnEnable(){Application.logMessageReceived+=Log;}void OnDisable(){Application.logMessageReceived-=Log;}void Log(string text,string trace,LogType type){if(!failed&&(type==LogType.Error||type==LogType.Exception))Check(false,"Runtime error: "+text);}
 static double Rms(string file){byte[] b=File.ReadAllBytes(file);double energy=0,peak=0;for(int i=44;i<b.Length;i+=2){double value=BitConverter.ToInt16(b,i)/32768.0;energy+=value*value;peak=Math.Max(peak,Math.Abs(value));}File.WriteAllText(file+".measure.txt","peak="+peak+" rms="+Math.Sqrt(energy/((b.Length-44)/2)));return Math.Sqrt(energy/((b.Length-44)/2));}
 static double ChannelRms(string file,int channel){var b=File.ReadAllBytes(file);double energy=0;int count=0;for(int i=44+channel*2;i+1<b.Length;i+=4){double v=BitConverter.ToInt16(b,i)/32768.0;energy+=v*v;count++;}return Math.Sqrt(energy/Math.Max(1,count));}
 IEnumerator Record(string name,Vector3 position){car.Body.position=position;car.transform.position=position;Physics.SyncTransforms();yield return new WaitForSecondsRealtime(.6f);var tap=listener.gameObject.AddComponent<TurboNativeAudioTap>();tap.Begin();yield return new WaitForSecondsRealtime(2);tap.Finish(folder+"/"+name+".wav");Destroy(tap);}
 IEnumerator Start(){Application.runInBackground=true;RoadEngineAudio.AllowBackgroundForTests=true;while((listener=FindAnyObjectByType<AudioListener>())==null)yield return null;yield return new WaitForSecondsRealtime(.5f);car=TrafficWorld.CreateCar("Isolated NPC engine",new WorkshopBuild(),0);car.externalInput=true;car.commandedPedal=1;car.commandedHandbrake=false;for(int i=0;i<100;i++)car.Tick(.02f);car.enabled=false;car.Body.isKinematic=true;var ear=listener.transform.position;yield return Record("Near_3m",ear+listener.transform.right*3);yield return Record("Left_3m",ear-listener.transform.right*3);yield return Record("Middle_25m",ear+listener.transform.right*25);yield return Record("Far_90m",ear+listener.transform.right*90);double near=Rms(folder+"/Near_3m.wav"),middle=Rms(folder+"/Middle_25m.wav"),far=Rms(folder+"/Far_90m.wav");Check(ChannelRms(folder+"/Near_3m.wav",1)>ChannelRms(folder+"/Near_3m.wav",0)*2&&ChannelRms(folder+"/Left_3m.wav",0)>ChannelRms(folder+"/Left_3m.wav",1)*2,"Actual NPC pass-by pans to the correct listener side");Check(near>.0001,"Actual listener captures audible nearby NPC engine");Check(near>middle*2,"Actual listener NPC level decreases substantially at25metres");Check(far<near*.001,"Actual distant NPC engine is silent rather than constant background drone");Check(car.GetComponent<RoadEngineAudio>().AudibleGain==0,"Runtime NPC signal is gated outside52metres");Check(car.GetComponentsInChildren<AudioSource>().Length==1,"NPC has one engine source without duplicate loops");Destroy(car.gameObject);yield return new WaitForSecondsRealtime(.2f);var cars=new List<FinchVehicle>();for(int i=0;i<9;i++){var npc=TrafficWorld.CreateCar("Voice budget "+i,new WorkshopBuild(),0);npc.commandedPedal=1;for(int n=0;n<100;n++)npc.Tick(.02f);npc.enabled=false;npc.Body.isKinematic=true;npc.transform.position=ear+listener.transform.right*(3+i*.2f);cars.Add(npc);}yield return new WaitForSecondsRealtime(.6f);Check(cars.Count(n=>n.GetComponent<RoadEngineAudio>().AudibleGain>0)<=6,"Dense traffic limits audible engine budget to nearest six cars");var dense=listener.gameObject.AddComponent<TurboNativeAudioTap>();dense.Begin();yield return new WaitForSecondsRealtime(2);dense.Finish(folder+"/Dense_Nine_Cars.wav");Destroy(dense);byte[] mix=File.ReadAllBytes(folder+"/Dense_Nine_Cars.wav");int clipped=0;for(int n=44;n<mix.Length;n+=2)if(Math.Abs((int)BitConverter.ToInt16(mix,n))>=32760)clipped++;Check(clipped==0,"Actual dense full-load NPC mix has no clipped samples");Rms(folder+"/Dense_Nine_Cars.wav");foreach(var npc in cars)Destroy(npc.gameObject);yield return new WaitForSecondsRealtime(.3f);DrivingUnits.FileOverrideForTests=folder+"/isolated-units.json";DrivingUnits.Reload();Check(DrivingSettingsView.Instance.Open(),"Actual Settings screen opens from menu");Screen.SetResolution(1400,800,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.4f);Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.6f);Check(DrivingUnits.Save(false)&&!DrivingUnits.Mph,"Native settings persists metric choice in isolated file");yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(folder+"/Speed_Unit_Settings.png");yield return new WaitForSecondsRealtime(.5f);Check(new FileInfo(folder+"/Speed_Unit_Settings.png").Length>50000,"Settings page renders cleanly in actual player");DrivingSettingsView.Instance.Close();DrivingUnits.FileOverrideForTests=null;DrivingUnits.Reload();Check(!failed,"NPC distance-audio native run has no runtime errors");Application.Quit(0);}
}
}
